{
  "headline": "FDA's records trace our supply to a plant classified OAI 150 days before the posting",
  "headline_cites": ["D11"],
  "sentences": [
    {
      "text": "FDA first posted the fentanyl citrate injection shortage on 2012-01-01 and it remains current as of 2026-10-21.",
      "cites": ["E29", "E28"]
    },
    {
      "text": "The Hospira, Inc. plant (FEI 1021343) that manufactures the product used at Corvale East and Corvale General received an OAI classification on 2010-01-19, 712 days before the posting.",
      "cites": ["E9", "D6"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2010-04-12, 629 days before the posting.",
      "cites": ["E16", "D7"]
    },
    {
      "text": "Two additional OAI inspections ended on 2011-06-17 and 2011-08-04, 198 and 150 days before the posting respectively.",
      "cites": ["E10", "D10", "E11", "D11"]
    },
    {
      "text": "The Hikma Pharmaceuticals USA Inc. plant (FEI 2220525) supplying Corvale General and Corvale Lakeside has only VAI inspections, the most recent ending 2024-06-12.",
      "cites": ["E24", "E25"]
    },
    {
      "text": "Corvale East holds 144 units of the Hospira product with 18.0 daily use, while Corvale General holds 348 units of the same product with 19.3 daily use.",
      "cites": ["E1", "E5"]
    }
  ]
}
